// A web package published the way many CommonJS packages publish their
// factory: the function is the module (`export =`), and a namespace of the
// same name re-exports it as a named export and as `default`.
type AliasedWeb = typeof web;

declare namespace web {
  export interface Request {
    path: string;
  }

  export interface Reply {
    send(body: unknown): void;
  }

  export type Handler = (request: Request, reply: Reply, next: () => void) => void;

  export interface App {
    get(path: string, handler: Handler): App;
    /** Serves `child` under `prefix`: another app, or a handler for every path below it. */
    use(prefix: string, child: App | Handler): App;
  }

  export const web: AliasedWeb;
  export { web as default };
}

declare function web(): web.App;

export = web;
